     3	import (
     4		"strings"
     5	
     6		tea "charm.land/bubbletea/v2"
     7		"charm.land/lipgloss/v2"
     8	
     9		"github.com/anthnel/devdesk/internal/ui/overlay"
    10		"github.com/anthnel/devdesk/internal/ui/theme"
    11	)
    12	
    13	// View is the program's frame. The router is the only place that sets the
    14	// terminal state (alternate screen now), the views only provide content.
    15	func (a *App) View() tea.View {
    16		v := tea.NewView(a.Render())
    17		v.AltScreen = true
    18		return v
    19	}
    20	
    21	// Render renders the interface: header, title line, viewport, footer (Rule 124).
    22	// An open overlay replaces the whole thing.
    23	func (a *App) Render() string {
    24		if overlay := a.activeOverlay(); overlay != "" {
    25			return lipgloss.Place(a.width, a.height, lipgloss.Center, lipgloss.Center, overlay,
    26				lipgloss.WithWhitespaceStyle(lipgloss.NewStyle().Background(theme.ColorBackground)))
    27		}
    28	
    29		header := a.renderHeader() + "\n" + a.renderTitleLine()
    30		body := a.renderBody()
    31		footer := a.renderViewFooter()
    32		inner := fitHeight(header, body, footer, a.height)
    33	
    34		placed := lipgloss.Place(a.width, a.height, lipgloss.Left, lipgloss.Top, inner,
    35			lipgloss.WithWhitespaceStyle(lipgloss.NewStyle().Background(theme.ColorBackground)))
    36		return a.withPalette(placed)
    37	}
    38	
    39	// withPalette draws the open command palette over the final screen. The
    40	// composition happens after fitHeight and Place, on exactly height lines of
    41	// width cells, so the geometry is in screen rows whatever the view is.
    42	func (a *App) withPalette(screen string) string {
    43		lines := a.paletteLines()
    44		if len(lines) == 0 {
    45			return screen
    46		}
    47		r := a.paletteRect()
    48		composed := overlay.Compose(strings.Split(screen, "\n"), lines, r.X, r.Y, a.width)
    49		return strings.Join(composed, "\n")
    50	}
    51	
    52	// fitHeight stacks header, body and footer in at most height lines.
    53	// lipgloss.Place pads a short block but never crops a tall one, so on a very
    54	// small terminal (header 8 + title 1 + the viewport's minimum + footer) the
    55	// frame would be taller than the screen. The surplus is taken from the body
    56	// first, bottom lines first: the footer carries the messages, so it outranks
    57	// viewport rows. If header and footer alone are taller than the terminal, the
    58	// stack is cut to its first height lines, the simplest floor. At normal
    59	// heights nothing is cut.
    60	func fitHeight(header, body, footer string, height int) string {
    61		parts := []string{header}
    62		if body != "" {
    63			parts = append(parts, body)
    64		}
    65		if footer != "" {
    66			parts = append(parts, footer)
    67		}
    68		lines := strings.Split(strings.Join(parts, "\n"), "\n")
    69		excess := len(lines) - height
    70		if height <= 0 || excess <= 0 {
    71			return strings.Join(lines, "\n")
    72		}
    73	
    74		headerLen := strings.Count(header, "\n") + 1
    75		bodyLen := 0
    76		if body != "" {
    77			bodyLen = strings.Count(body, "\n") + 1
    78		}
    79		cut := min(excess, bodyLen)
    80		if cut > 0 {
    81			end := headerLen + bodyLen
    82			lines = append(lines[:end-cut], lines[end:]...)
    83		}
    84		if len(lines) > height {
    85			lines = lines[:height]
    86		}
    87		return strings.Join(lines, "\n")
    88	}
    89	
    90	// activeOverlay returns the overlay to draw instead of the view, or "" when
    91	// there is none. The order matches the one handleKeyMsg dispatches in, so the
    92	// overlay holding the keyboard is the one on screen.
    93	func (a *App) activeOverlay() string {
    94		switch {
    95		case a.switchingTo != "":
    96			return a.renderContextSwitchingOverlay()
    97		case a.showHelp:
    98			return a.renderHelpOverlay()
    99		case a.showContextList:
   100			return a.renderContextListOverlay()
   101		}
   102		return ""
   103	}
   104	
   105	// renderBody fills the viewport with the active view's content, padded to the
   106	// full inner width so no line shows the terminal's own background (Rule 115).
   107	func (a *App) renderBody() string {
   108		content := "View not found: " + string(a.currentView)
   109		if view, ok := a.views[a.currentView]; ok {
   110			content = view.Render()
   111		}
   112	
   113		innerWidth := a.viewport.Width() - 2 // -2 for the borders
   114		if a.frameless() {
   115			innerWidth = a.viewport.Width()
   116		}
   117		a.viewport.SetContent(lipgloss.NewStyle().
   118			Background(theme.ColorBackground).
   119			Foreground(theme.ColorText).
   120			Width(innerWidth).
   121			Render(content))
   122	
   123		body := a.viewport.View()
   124	
   125		// Rule 136: with a filter bar below it, the viewport's bottom corners become
   126		// T-junctions so the two form one closed rectangle.
   127		if view, ok := a.views[a.currentView]; ok {
   128			if fbv, ok := view.(FilterBarView); ok && fbv.FilterBarVisible() {
   129				body = replaceViewportBottomCorners(body)
   130			}
   131		}
   132		return body
   133	}
   134	
   135	// renderTitleLine draws the viewport's top border carrying the view's title —
