package app

import (
	"os"
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/testutil/colorprofile"
	"github.com/anthnel/devdesk/internal/ui/testutil"
	"github.com/charmbracelet/lipgloss"
)

func benchRouter(t *testing.T) *App {
	v := &measuredView{rows: 20, spinner: true}
	a := routerAt(t, v, measureWidth, measureHeight)
	a.Update(testutil.Key("down"))
	a.Update(jobs.StartMsg{Run: scanRun("default", "a")})
	a.Update(jobs.FrameMsg{Frame: "⠋", Blink: true})
	return a
}

func TestZZViewBench(t *testing.T) {
	if os.Getenv("ZZ_BENCH") == "" {
		t.Skip()
	}
	if os.Getenv("ZZ_TRUECOLOR") == "1" {
		colorprofile.TrueColor(t)
	}
	a := benchRouter(t)
	s := a.View()
	t.Logf("profile=%v len=%d sgr=%d", lipgloss.ColorProfile(), len(s), strings.Count(s, "\x1b["))
	if f := os.Getenv("ZZ_DUMP"); f != "" {
		_ = os.WriteFile(f, []byte(s), 0o644)
	}
	r := testing.Benchmark(func(b *testing.B) {
		b.ReportAllocs()
		for i := 0; i < b.N; i++ {
			_ = a.View()
		}
	})
	t.Logf("BENCH %s %d ns/op %d B/op %d allocs/op", os.Getenv("ZZ_TAG"), r.NsPerOp(), r.AllocedBytesPerOp(), r.AllocsPerOp())
}
EOF
