package app

import (
	"os"
	"strings"
	"testing"

	"github.com/charmbracelet/x/ansi"
)

func TestZZWidth(t *testing.T) {
	if os.Getenv("ZZ_BENCH") == "" {
		t.Skip()
	}
	ascii := strings.Repeat("row 01  some name that stays the same ", 3)[:116]
	styled := "\x1b[38;2;200;200;200;48;2;30;30;30m" + ascii + "\x1b[m"
	uni := "● " + ascii[:114]
	for _, c := range []struct{ n, s string }{{"ascii", ascii}, {"styled", styled}, {"bullet", uni}} {
		r := testing.Benchmark(func(b *testing.B) {
			for i := 0; i < b.N; i++ {
				_ = ansi.StringWidth(c.s)
			}
		})
		t.Logf("WIDTH %s %d ns/op", c.n, r.NsPerOp())
	}
}
EOF
(cd $S/$v && echo == $v && ZZ_BENCH=1 GOMAXPROCS=1 go test ./internal/app/ -run TestZZWidth -v -count=1 | grep WIDTH); done

